 "content": "from collections import deque


def transform(grid):
    """Recolor enclosed zero regions by their square interior side length."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    outside = set()
    queue = deque()

    # Mark zero-valued background connected to the grid boundary.
    for r in range(h):
        for c in range(w):
            if (r in (0, h - 1) or c in (0, w - 1)) and grid[r][c] == 0:
                if (r, c) not in outside:
                    outside.add((r, c))
                    queue.append((r, c))
    while queue:
        r, c = queue.popleft()
        for nr, nc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
            if (0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0
                    and (nr, nc) not in outside):
                outside.add((nr, nc))
                queue.append((nr, nc))

    # The demos map interior side lengths 3, 5, 7 to colors 8, 4, 3.
    fill_color = {3: 8, 5: 4, 7: 3}
    visited = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or (r, c) in outside or (r, c) in visited:
                continue
            component = [(r, c)]
            visited.add((r, c))
            for cr, cc in component:
                for nr, nc in ((cr - 1, cc), (cr + 1, cc), (cr, cc - 1), (cr, cc + 1)):
                    if (0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0
                            and (nr, nc) not in outside and (nr, nc) not in visited):
                        visited.add((nr, nc))
                        component.append((nr, nc))
            side = max(
                max(cr for cr, _ in component) - min(cr for cr, _ in component) + 1,
                max(cc for _, cc in component) - min(cc for _, cc in component) + 1,
            )
            color = fill_color.get(side)
            if color is not None:
                for cr, cc in component:
                    out[cr][cc] = color
    return out


if __name__ == "__main__":
    print("transform(grid) ready")
